-- Seed common desktop CPUs found in Korean new/used PC listings.
-- Specification sources:
--   Intel Desktop and Boxed Processors Comparison Chart (official, reviewed March 2026)
--   AMD Processor Specifications catalog (official, accessed 2026-07-16)
-- Benchmark columns remain NULL until a licensed/versioned benchmark source is selected.

insert into public.cpu_specs (
  cpu_name,
  manufacturer,
  architecture,
  cores,
  threads,
  base_clock_ghz,
  boost_clock_ghz,
  cache_mb,
  tdp_watts,
  source_url
)
